if (trimmed != null) {
 state.messages = trimmed.messages;
 final tokensAfter = _requestTokens();
 hooks.onPass(AutoCompactorPass(...same...));
 hooks.onDone(pass, tokensAfter);
 return (
   done: true,
   success: !shouldCompact(tokensAfter, window, settings) && !_overMessageCap(),
 );
