    this.maxAttempts = 3,
    this.baseBackoff = const Duration(seconds: 1),
    this.force = false,
    this.attemptBudget = const Duration(seconds: 300),
    this.totalBudget = const Duration(minutes: 15),
    this.runToken,
    this.messageCap,
    this.messageCapMargin = kMessageCapDefaultMargin,
  });

